import math

# 1) 函数 = 确定对应：一次函数就是最简单的模型
def linear(x, k=2.0, b=1.0):
    return k * x + b

for x in [-2.0, -1.0, 0.0, 1.0, 2.0]:
    print(f'x={x:>5}  f(x)={linear(x):>6.1f}')

# 2) 损失函数：衡量模型输出离真实答案有多远
def mse(k, xs, ys):
    total = 0.0
    for x, y in zip(xs, ys):
        total += (linear(x, k, 0.0) - y) ** 2
    return total / len(xs)

xs = [1.0, 2.0, 3.0]
ys = [3.0, 5.0, 7.0]        # 真实规律是 y = 2x + 1，这里先固定 b = 0
for k in [0.0, 1.0, 2.0, 3.0]:
    print(f'k={k}  loss={mse(k, xs, ys):.2f}')   # k = 2 时损失最小

# 3) 看形状：sigmoid 把任意实数压到 (0, 1)
def sigmoid(z):
    return 1 / (1 + math.exp(-z))

for z in [-4.0, -2.0, 0.0, 2.0, 4.0]:
    print(f'z={z:>5}  sigmoid={sigmoid(z):.4f}')

