quiz.solution:
def numeric_derivative(f, x, h=1e-5):
    return (f(x + h) - f(x - h)) / (2 * h)

def f(x):
    return x ** 3

print(round(numeric_derivative(f, 2.0), 6))
print(3 * 2.0 ** 2)
